namespace QuantForge.Core;public enum AndroidResearchQueueState{Prepared,Running,Complete,Blocked,Invalid}public sealed record AndroidResearchQueueItem(string DraftFingerprint,string DatasetFingerprint,string StrategyFingerprint,AndroidResearchQueueState State,string Message);public static class AndroidResearchQueueRules{public static AndroidResearchQueueItem Prepare(AndroidResearchLaunchDraft draft){if(!draft.Ready||draft.CanSubmitOrders)throw new InvalidOperationException("Only ready research-only drafts may enter the queue.");return new(draft.DraftFingerprint,draft.DatasetFingerprint,draft.StrategyFingerprint,AndroidResearchQueueState.Prepared,"Prepared for read-only research execution.");}public static AndroidResearchQueueItem Transition(AndroidResearchQueueItem item,AndroidResearchQueueState state,string message){if(string.IsNullOrWhiteSpace(message))throw new InvalidOperationException("Queue transition requires a message.");if(item.State is AndroidResearchQueueState.Complete or AndroidResearchQueueState.Blocked or AndroidResearchQueueState.Invalid)throw new InvalidOperationException("Terminal research queue items cannot transition.");return item with{State=state,Message=message};}}
